caddyfile:
{
    admin off
    persist_config off
    auto_https off
    storage file_system {
        root /tmp/diamond-w8-tls-proxy-3ozjinwg/caddy-data
    }
    servers {
        protocols h1 h2
    }
}
https://localhost:49017 {
    bind 127.0.0.1
    tls /tmp/diamond-w8-tls-proxy-3ozjinwg/certificates/localhost.pem /tmp/diamond-w8-tls-proxy-3ozjinwg/certificates/localhost.key
    reverse_proxy 127.0.0.1:57071 127.0.0.1:56803 {
        lb_policy round_robin
        header_up Host {http.request.hostport}
        header_up -Forwarded
        header_up -X-Forwarded-*
        health_uri /_diamond/health/ready
        health_headers {
            Host localhost:49017
        }
        health_interval 1s
    }
}
